package com.rudra.offlinepayment;
import android.app.*;import android.os.*;import android.widget.*;import android.view.*;import org.json.*;import java.io.*;import java.math.*;import java.net.*;import java.time.*;import java.util.*;import java.util.concurrent.*;
public class MainActivity extends Activity {
 final String PREF="offline_queue"; final ExecutorService io=Executors.newSingleThreadExecutor(); EditText from,to,amount,url;TextView info;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(28,32,28,20);ScrollView s=new ScrollView(this);s.addView(l);setContentView(s);TextView h=new TextView(this);h.setText("Offline Payment Demo — simulation only");h.setTextSize(22);l.addView(h);url=field(l,"API URL","http://10.0.2.2:8080/api/v1/payments");from=field(l,"Sender ID","alice");to=field(l,"Recipient ID","bob");amount=field(l,"Amount","25.00");btn(l,"Create offline intent",this::saveIntent);btn(l,"Send first queued intent over Bluetooth",this::sendBle);btn(l,"Sync queue directly over network",this::sync);info=new TextView(this);l.addView(info);count();}
 EditText field(LinearLayout l,String h,String v){EditText e=new EditText(this);e.setHint(h);e.setText(v);l.addView(e);return e;}void btn(LinearLayout l,String t,Runnable r){Button b=new Button(this);b.setText(t);b.setOnClickListener(v->r.run());l.addView(b);}
 void saveIntent(){try{BigDecimal a=new BigDecimal(amount.getText().toString());String x=from.getText().toString().trim(),y=to.getText().toString().trim();if(a.signum()<=0||a.scale()>2||x.isEmpty()||y.isEmpty()||x.equals(y))throw new Exception();Instant n=Instant.now();JSONObject j=new JSONObject();String id=UUID.randomUUID().toString();j.put("id",id);j.put("senderId",x);j.put("recipientId",y);j.put("amount",a.toPlainString());j.put("createdAt",n.toString());j.put("expiresAt",n.plusSeconds(3600).toString());getSharedPreferences(PREF,0).edit().putString(id,j.toString()).apply();info.setText("Saved locally. No network used.");count();}catch(Exception e){info.setText("Enter valid IDs and a positive amount (max 2 decimals).");}}
 void sendBle(){for(String id:getSharedPreferences(PREF,0).getAll().keySet()){String payload=getSharedPreferences(PREF,0).getString(id,null);if(payload!=null){Intent i=new Intent(this,BleSendActivity.class);i.putExtra("payload",payload);startActivity(i);return;}}info.setText("No queued intent to send.");}
 void sync(){String endpoint=url.getText().toString().replaceAll("/+$","")+"/relay";io.execute(()->{int n=0;try{for(String id:getSharedPreferences(PREF,0).getAll().keySet()){String body=getSharedPreferences(PREF,0).getString(id,null);if(body==null)continue;HttpURLConnection c=(HttpURLConnection)new URL(endpoint).openConnection();try{c.setRequestMethod("POST");c.setDoOutput(true);c.setConnectTimeout(8000);c.setReadTimeout(8000);c.setRequestProperty("Content-Type","application/json");try(OutputStream o=c.getOutputStream()){o.write(body.getBytes("UTF-8"));}int code=c.getResponseCode();if(code<200||code>=300)throw new IOException("HTTP "+code);try(InputStream in=c.getInputStream()){while(in.read()!=-1){}}}finally{c.disconnect();}getSharedPreferences(PREF,0).edit().remove(id).apply();n++;}int done=n;runOnUiThread(()->{info.setText("Synced "+done+" intent(s).");count();});}catch(Exception e){runOnUiThread(()->info.setText("Sync failed: "+e.getMessage()+"; unsent intents remain queued."));}});}
 void count(){info.setText("Queued: "+getSharedPreferences(PREF,0).getAll().size());}public void onDestroy(){super.onDestroy();io.shutdown();}
}
